def _card(data, cid):
    return next(d for d in data['deals'] if d['id'] == cid)


def _first(c, url):
    urls = [s[1] for s in c.get('src') or []]
    if url not in urls or urls[0] == url:
        return False
    c['src'] = [s for s in c['src'] if s[1] == url] + [s for s in c['src'] if s[1] != url]
    return True


def _profile_id(data, seed):
    import hashlib
    for i in range(100):
        cid = 'g' + hashlib.md5(('%s:%d' % (seed, i)).encode()).hexdigest()[:8]
        p = data['companies'].get(cid)
        if p is None or p.get('inn') == MOLOKO_PROFILE['inn']:
            return cid
    raise SystemExit('нет свободного id')


def _oneoff_apply(data, strict=True):
    import fact_edit_guard
    n = 0
    # тексты ONEOFF_TEXT
    for (cid, field), (old, new, _why) in ONEOFF_TEXT.items():
        c = _card(data, cid)
        head, tail = field.split('.')
        if c[head].get(tail) == new:
            continue
        assert c[head].get(tail) == old, (cid, field, c[head].get(tail))
        c[head][tail] = new
        if field in fact_edit_guard.FACT_FIELDS:
            fact_edit_guard.log(c, field, new, PWEM_REG_Q, DN_PWEM, ONEOFF_BY, ONEOFF_DAY)
        n += 1

    # --- g30404c73
    c = _card(data, 'g30404c73')
    if c.get('buyer_name') != PWEM_BUYER_NAME:
        assert c.get('buyer') == PWEM_BUYER_OLD and not c.get('buyer_name'), (c.get('buyer'), c.get('buyer_name'))
        c.pop('buyer')
        c['buyer_name'] = PWEM_BUYER_NAME
        fact_edit_guard.log(c, 'buyer', None, PWEM_REG_Q, DN_PWEM, ONEOFF_BY, ONEOFF_DAY)
        fact_edit_guard.log(c, 'buyer_name', PWEM_BUYER_NAME, PWEM_REG_Q, DN_PWEM, ONEOFF_BY, ONEOFF_DAY)
        c['party_evidence']['buyer'] = [{'value': PWEM_BUYER_NAME, 'field': 'buyer_name',
                                         'method': 'registry_owners', 'url': DN_PWEM}]
        notes = c.setdefault('accepted_notes', {})
        notes.setdefault('no_profile', {})['buyer'] = PWEM_NO_PROFILE_BUYER
        (notes.get('no_inn') or {}).pop('buyer', None)
        n += 1
    p = data['companies'][c['target']]
    if p.get('inn') != PWEM_INN:
        assert not p.get('inn'), p.get('inn')
        p['inn'], p['legal_short'] = PWEM_INN, PWEM_LEGAL
        (c.get('accepted_notes', {}).get('no_inn') or {}).pop('target', None)
        if not (c.get('accepted_notes') or {}).get('no_inn'):
            c.get('accepted_notes', {}).pop('no_inn', None)
        n += 1
    if SMART not in [s[1] for s in c['src']]:
        assert not strict, 'сначала review.py --write: источник Smart-Lab добавляет таблица'
        print('(сухой прогон: Smart-Lab появится после review.py --write — перестановка пропущена)')
    elif _first(c, SMART):
        n += 1

    # --- g7ad2f3e2
    c = _card(data, 'g7ad2f3e2')
    if c.get('date') != CHATIX_DATE_NEW:
        assert c.get('date') == CHATIX_DATE_OLD and c.get('date_basis') == 'announcement', (c.get('date'), c.get('date_basis'))
        c['date'], c['date_basis'] = CHATIX_DATE_NEW, 'registry'
        fact_edit_guard.log(c, 'date', CHATIX_DATE_NEW, CHATIX_DATE_Q, DN_CHATIX, ONEOFF_BY, ONEOFF_DAY)
        n += 1
    p = data['companies'][CHATIX_PROFILE]
    if p.get('desc') != CHATIX_DESC_NEW:
        assert p.get('desc') == CHATIX_DESC_OLD, p.get('desc')
        p['desc'], p['inn'], p['legal_short'] = CHATIX_DESC_NEW, CHATIX_INN, 'ООО «Чатикс»'
        notes = c.setdefault('accepted_notes', {})
        (notes.get('no_inn') or {}).pop('target', None)
        if not notes.get('no_inn'):
            notes.pop('no_inn', None)
        notes.setdefault('no_profile', {})['buyer'] = CHATIX_NO_PROFILE_BUYER
        notes.setdefault('checked', {})['registry_owners'] = CHATIX_CHECKED
        n += 1
    if EDIN not in [s[1] for s in c['src']]:
        assert not strict, 'сначала review.py --write: источник «Единорога» добавляет таблица'
        print('(сухой прогон: «Единорог» появится после review.py --write — перестановка пропущена)')
    elif _first(c, EDIN):
        n += 1

    # --- ga187c62e: профиль предмета
    c = _card(data, 'ga187c62e')
    if not c.get('target'):
        pid = _profile_id(data, 'Молочная столица ' + MOLOKO_PROFILE['inn'])
        data['companies'].setdefault(pid, dict(MOLOKO_PROFILE))
        c['target'] = pid
        fact_edit_guard.log(c, 'target', pid, MOLOKO_Q, DN_MOLOKO, ONEOFF_BY, ONEOFF_DAY)
        notes = c.setdefault('accepted_notes', {})
        (notes.get('no_profile') or {}).pop('target', None)
        notes.setdefault('checked', {})['registry_owners'] = MOLOKO_CHECKED
        c.setdefault('party_evidence', {})['target'] = [{'value': 'Молочная столица', 'field': 'target',
                                                         'method': 'registry_owners', 'url': DN_MOLOKO}]
        n += 1

    # --- geaa2c705: продавец — фонд «Сигма 66»
    c = _card(data, 'geaa2c705')
    if c.get('seller') != BACH_SELLER_NEW:
        assert c.get('seller') == BACH_SELLER_OLD and not c.get('seller_id'), (c.get('seller'), c.get('seller_id'))
        c['seller'] = BACH_SELLER_NEW
        fact_edit_guard.log(c, 'seller', BACH_SELLER_NEW, BACH_Q, VED, ONEOFF_BY, ONEOFF_DAY)
        r = c.setdefault('retracted', {}).setdefault('seller', [])
        if BACH_SELLER_OLD not in r:
            r.append(BACH_SELLER_OLD)
        c['party_evidence']['seller'] = [{'value': BACH_SELLER_NEW, 'field': 'seller',
                                          'method': 'registry_owners', 'url': VED}]
        c['accepted_notes']['no_profile']['seller'] = BACH_NO_PROFILE_SELLER
        n += 1
    return n


# Реестр ИНН (pipeline/fns_registry.py, блок `REGISTRY += [...]` перед `def by_company_id`): три профиля,
# у которых ИНН подтвержден двумя источниками. Дописывается только при --write и только если записи нет.
def _registry_rows(data):
    pid = _profile_id(data, 'Молочная столица ' + MOLOKO_PROFILE['inn'])
    return [
        ('g29eeaeb1', PWEM_INN, 'Вычитка g30404c73 (2026-11-25): ООО ИК «Управление частным капиталом» (с ноября 2026 года — '
         'ООО «ИК «8 Элемент»), ОГРН 1215200023103 — тот же, что в записи LEI 253400HKFCWG2ZXPJL04; ИНН — поиск datanewton '
         'по ОГРН, директор Конюхова Я.В. — гендиректор PWeM Invest по релизу; Нижегородская область, управление ценными бумагами.'),
        (CHATIX_PROFILE, CHATIX_INN, 'Вычитка g7ad2f3e2 (2026-11-25): ООО «Чатикс», ОГРН 1269600007533 (datanewton): директор '
         'Демьянов К.С. — тот же, что называет rusven («ИП Демьянов К.С.»), а история участников показывает вход ООО «Чак Виси» '
         'с 10% — ту же долю, что «Единорог» (по «Контур Фокусу»); ОКВЭД — ИТ, Свердловская область, регистрация 05.03.2026.'),
        (pid, MOLOKO_PROFILE['inn'], 'Вычитка ga187c62e (2026-11-25): ООО «Молочная столица», ОГРН 1154827011426 (datanewton): '
         'директор Саунин С.Ю., регистрация 24.06.2015, перевозка грузов специализированным транспортом, Липецкая область — '
         'все совпадает с Абирегом; ИНН тот же, что в записи EMIS (приемка 23 ноября 2026); история участников: Кремнева В.Н. '
         '→ Кремнев И.А. 12.11.2026.'),
    ]


def _write_registry(data, root):
    import os
    import sys
    sys.path.insert(0, os.path.join(root, 'pipeline'))
    import fns_registry
    have = fns_registry.by_company_id()
    rows = [r for r in _registry_rows(data) if r[0] not in have]
    if not rows:
        return 0
    path = os.path.join(root, 'pipeline', 'fns_registry.py')
    src = open(path, encoding='utf-8').read()
    block = '# Вычитка базы, партия 2026_11_25_b (pipeline/ingest/fixes/reread_2026_11_25_b.py).\nREGISTRY += [\n'
    for cid, inn, why in rows:
        block += ('    {"company_id": %r, "decision": "confirmed", "inn": %r,\n     "reason": %r,\n     "date": %r},\n'
                  % (cid, inn, why, ONEOFF_DAY))
    block += ']\n\n'
    anchor = 'def by_company_id()'
    assert src.count(anchor) == 1
    open(path, 'w', encoding='utf-8').write(src.replace(anchor, block + anchor))
    return len(rows)


def _oneoff_main(write):
    import json
    import os
    import sys
    root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))))
    sys.path.insert(0, os.path.join(root, 'pipeline'))
    import fact_edit_guard
    import mass_edit_guard
    path = os.path.join(root, 'static', 'data', 'deals_promoted.json')
    raw = open(path, encoding='utf-8').read()
    old, data = json.loads(raw), json.loads(raw)
    n = _oneoff_apply(data, strict=write)
    if not n:
        print('Уже применено.')
        return 0
    mass_edit_guard.check(old, data, os.environ.get('MASS_OK'))
    bad = fact_edit_guard.unbacked(old, data)
    assert not bad, bad
    if not write:
        print('Сухой прогон: %d правок. Запись — с ключом --write.' % n)
        return 0
    fresh_raw = open(path, encoding='utf-8').read()
    fresh = json.loads(fresh_raw)
    _oneoff_apply(fresh)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(json.dumps(fresh, ensure_ascii=False, indent=1) + ('\n' if fresh_raw.endswith('\n') else ''))
    print('ЗАПИСАНО: %d правок; реестр ИНН: %d записей.' % (n, _write_registry(fresh, root)))
    return 0


if __name__ == '__main__':
    import sys
    sys.exit(_oneoff_main('--write' in sys.argv[1:]))
